def est_lines(text, box_w_in, size_pt, char_factor=AVG_CHAR_PT):
    if not text:
        return 0
    chars_per_line = max(1, int(box_w_in * 72 / (size_pt * char_factor)))
    lines = 0
    for raw in text.split("\n"):
        # soft-wrap: a short line that nearly fills the box may wrap; be conservative
        lines += max(1, -(-len(raw) // chars_per_line)) if len(raw) > 0.95 * chars_per_line else 1
    return lines

